"""Analytics: cohort records."""

TABLE = "cohort"
FIELDS = ('month', 'customers', 'orders')


def ensure_table(conn):
    conn.execute("CREATE TABLE IF NOT EXISTS cohort (id INTEGER PRIMARY KEY, month TEXT, customers TEXT, orders TEXT)")


def create(conn, month, customers, orders):
    ensure_table(conn)
    cur = conn.execute("INSERT INTO cohort(month, customers, orders) VALUES (?,?,?)", (month, customers, orders,))
    conn.commit()
    return cur.lastrowid


def get(conn, row_id):
    ensure_table(conn)
    return conn.execute("SELECT * FROM cohort WHERE id=?", (row_id,)).fetchone()


def list_all(conn, limit=100):
    ensure_table(conn)
    return conn.execute("SELECT * FROM cohort ORDER BY id LIMIT ?", (limit,)).fetchall()


